#include "rbtree.h"

#include <assert.h>
#include <stddef.h>
#include <stdio.h>

/* Provided by tests/fault_malloc.c: forces a specific rb_malloc call inside
 * rb_create to return NULL, without touching libc malloc. */
extern void fault_malloc_arm(int nth_call_to_fail);
extern void fault_malloc_disarm(void);

static void noop_free(void *value)
{
    (void)value;
}

static void count_cb(const char *key, void *value, void *ctx)
{
    (void)key;
    (void)value;
    (*(int *)ctx)++;
}

typedef struct {
    const char *name;
    rb_value_free_fn value_free;
    int fail_at;          /* 0 = no injected malloc failure */
    int expect_nonnull;
} create_case_t;

/* Cases 1-4: baseline success (with/without value_free), and injected
 * failure on each of rb_create's two allocations (the struct, then the
 * nil sentinel). A successful tree is destroyed at the end of each
 * iteration, which also exercises case 6 (destroy-after-success is
 * crash-free and memcheck-clean) for every row that returns non-NULL. */
static const create_case_t create_cases[] = {
    { "create_null_value_free",    NULL,      0, 1 },
    { "create_nonnull_value_free", noop_free, 0, 1 },
    { "create_fail_first_alloc",   NULL,      1, 0 },
    { "create_fail_second_alloc",  NULL,      2, 0 },
};

static void test_rb_create(void)
{
    size_t n = sizeof create_cases / sizeof create_cases[0];
    /* invariant: each iteration leaves no allocation armed and no tree
     * leaked, regardless of whether rb_create succeeded. */
    for (size_t i = 0; i < n; i++) {
        const create_case_t *c = &create_cases[i];

        if (c->fail_at)
            fault_malloc_arm(c->fail_at);
        rbtree_t *t = rb_create(c->value_free);
        if (c->fail_at)
            fault_malloc_disarm();

        assert((t != NULL) == c->expect_nonnull);

        if (t) {
            assert(rb_size(t) == 0);
            assert(rb_find(t, "probe") == NULL);
            int calls = 0;
            rb_foreach(t, count_cb, &calls);
            assert(calls == 0);
            rb_destroy(t);
        }
        printf("ok - %s\n", c->name);
    }

    /* Case 5: two live trees don't share hidden state. */
    {
        rbtree_t *a = rb_create(NULL);
        rbtree_t *b = rb_create(NULL);
        assert(a && b && a != b);
        assert(rb_size(a) == 0 && rb_size(b) == 0);
        rb_destroy(a);
        assert(rb_size(b) == 0);
        rb_destroy(b);
        printf("ok - create_independent_instances\n");
    }

    /* Case 7: rb_destroy is documented NULL-safe. */
    {
        rb_destroy(NULL);
        printf("ok - create_destroy_null_safe\n");
    }
}

int main(void)
{
    test_rb_create();
    return 0;
}

