    { "create_null_value_free",    NULL,      0, 1 },
    { "create_nonnull_value_free", noop_free, 0, 1 },
    { "create_fail_first_alloc",   NULL,      1, 0 },
    { "create_fail_second_alloc",  NULL,      2, 0 },
};

static void test_rb_create(void)
{
    size_t n = sizeof create_cases / sizeof create_cases[0];
