            int rc = rb_insert(t, "delta", v);
            fault_malloc_disarm();

            assert(rc == -1);
            assert(!was_freed(v));
            assert(rb_size(t) == 0);
            free(v);   /* caller still owns it; must not double-free */
        }
        rb_destroy(t);
        printf("ok - insert_failure_value_not_consumed\n");
    }

